1	package handover
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// Service 在 Store 之上实现班次交接的全部业务规则。
11	type Service struct {
12		store *Store
13		now   func() time.Time
14	}
15	
16	// NewService 创建业务服务。
17	func NewService(store *Store) *Service {
18		return &Service{store: store, now: time.Now}
19	}
20	
21	// nowAt 供测试固定处理时间。
22	func (svc *Service) nowAt(fn func() time.Time) { svc.now = fn }
23	
24	func clean(s string) string { return strings.TrimSpace(s) }
25	
26	func requireNonEmpty(field, v string) error {
27		if clean(v) == "" {
28			return fmt.Errorf("%w：%s不能为空", ErrInvalidInput, field)
29		}
30		return nil
31	}
32	
33	func intervalsOverlap(s1, e1, s2, e2 time.Time) bool {
34		// 前班结束恰好等于后班开始（端点相等）不算重叠。
35		return s1.Before(e2) && s2.Before(e1)
36	}
37	
38	// notePair 返回无序班次编号对，作为重叠说明的稳定键。
39	func notePair(a, b string) (string, string) {
40		if a <= b {
41			return a, b
42		}
43		return b, a
44	}
45	
46	func findShift(d *Data, id string) (*Shift, int) {
47		for i := range d.Shifts {
48			if d.Shifts[i].ID == id {
49				return &d.Shifts[i], i
50			}
51		}
52		return nil, -1
53	}
54	
55	func findItem(d *Data, id string) (*Item, int) {
56		for i := range d.Items {
57			if d.Items[i].ID == id {
58				return &d.Items[i], i
59			}
60		}
61		return nil, -1
62	}
63	
64	func findHandover(d *Data, id string) (*Handover, int) {
65		for i := range d.Handovers {
66			if d.Handovers[i].ID == id {
67				return &d.Handovers[i], i
68			}
69		}
70		return nil, -1
71	}
72	
73	func findEntry(h *Handover, itemID string) (*HandoverEntry, int) {
74		for i := range h.Entries {
75			if h.Entries[i].ItemID == itemID {
76				return &h.Entries[i], i
77			}
78		}
79		return nil, -1
80	}
81	
82	func findNote(d *Data, a, b string) *OverlapNote {
83		x, y := notePair(a, b)
84		for i := range d.Notes {
85			if d.Notes[i].ShiftA == x && d.Notes[i].ShiftB == y {
86				return &d.Notes[i]
87			}
88		}
89		return nil
90	}
91	
92	// currentItemsOfShift 返回与某班次相关的当前事项，按编号排列、每项只列一次。
93	// 用于进行中班次的当前信息展示，以及缺少结束时记录的旧数据班次。
94	func currentItemsOfShift(d *Data, shiftID string) []Item {
95		out := []Item{}
96		seen := map[string]bool{}
97		for _, it := range d.Items {
98			if seen[it.ID] {
99				continue
100			}
101			if it.OriginShiftID == shiftID || it.CurrentShiftID == shiftID || contains(it.ShiftIDs, shiftID) {
102				seen[it.ID] = true
103				out = append(out, it)
104			}
105		}
106		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
107		return out
108	}
109	
110	// hasEffectiveNote 报告两个班次之间是否已保存至少一条有效重叠说明：
111	// 正文去掉首尾空白后仍有内容。记录存在但正文缺失、为空或全是空白
112	// （空格、制表符、换行）都不算已说明；与存放次序无关，只认有效正文。
113	func hasEffectiveNote(d *Data, a, b string) bool {
114		x, y := notePair(a, b)
115		for i := range d.Notes {
116			if d.Notes[i].ShiftA == x && d.Notes[i].ShiftB == y && clean(d.Notes[i].Note) != "" {
117				return true
118			}
119		}
120		return false
121	}
122	
123	// CreateShift 建立班次。岗位、负责人必填，结束时间必须晚于开始时间。
124	// 同一岗位按实际时刻比较区间：前班结束恰好等于后班开始不算重叠；
125	// 与同岗位已存班次存在重叠时 overlapNote 必须非空，说明会一并保存。
126	// 不同岗位互不影响。
127	func (svc *Service) CreateShift(position, owner string, start, end time.Time, overlapNote string) (Shift, error) {
128		position = clean(position)
129		owner = clean(owner)
130		overlapNote = clean(overlapNote)
131		if err := requireNonEmpty("岗位", position); err != nil {
132			return Shift{}, err
133		}
134		if err := requireNonEmpty("负责人", owner); err != nil {
135			return Shift{}, err
136		}
137		if !end.After(start) {
138			return Shift{}, fmt.Errorf("%w：结束时间必须晚于开始时间（开始 %s，结束 %s）",
139				ErrInvalidInput, start.Format(time.RFC3339), end.Format(time.RFC3339))
140		}
141	
142		var created Shift
143		err := svc.store.mutate(func(d *Data) error {
144			var overlapping []Shift
145			for _, sh := range d.Shifts {
146				if sh.Position == position && intervalsOverlap(start, end, sh.Start, sh.End) {
147					overlapping = append(overlapping, sh)
148				}
149			}
150			if len(overlapping) > 0 && overlapNote == "" {
151				ids := make([]string, len(overlapping))
152				for i, sh := range overlapping {
153					ids[i] = fmt.Sprintf("%s（%s ~ %s）", sh.ID, sh.Start.Format(time.RFC3339), sh.End.Format(time.RFC3339))
154				}
155				return fmt.Errorf("%w：与同岗位班次 %s 区间重叠，必须填写重叠说明",
156					ErrOverlap, strings.Join(ids, "、"))
157			}
158	
159			d.ShiftSeq++
160			now := svc.now()
161			created = Shift{
162				ID:        fmt.Sprintf("S%03d", d.ShiftSeq),
163				Position:  position,
164				Owner:     owner,
165				Start:     start,
166				End:       end,
167				CreatedAt: now,
168			}
169			d.Shifts = append(d.Shifts, created)
170	
171			// 为每个尚未登记说明的重叠班次保存说明；已有说明的不重复保存。
172			for _, sh := range overlapping {
173				if findNote(d, created.ID, sh.ID) != nil {
174					continue
175				}
176				d.NoteSeq++
177				x, y := notePair(created.ID, sh.ID)
178				d.Notes = append(d.Notes, OverlapNote{
179					ID:        fmt.Sprintf("N%03d", d.NoteSeq),
180					Position:  position,
181					ShiftA:    x,
182					ShiftB:    y,
183					Note:      overlapNote,
184					CreatedAt: now,
185				})
186			}
187			return nil
188		})
189		if err != nil {
190			return Shift{}, err
191		}
192		// 返回独立副本：调用方保留的建立结果（关闭时间等指针字段）不与系统
193		// 保存的班次共享内存。
194		return cloneShift(created), nil
195	}
196	
197	// AddOverlapNote 为同岗位两个重叠班次保存重叠说明。
198	func (svc *Service) AddOverlapNote(shiftA, shiftB, note string) (OverlapNote, error) {
199		note = clean(note)
200		if err := requireNonEmpty("重叠说明", note); err != nil {
201			return OverlapNote{}, err
202		}
203		if clean(shiftA) == clean(shiftB) {
204			return OverlapNote{}, fmt.Errorf("%w：重叠说明需要两个不同的班次", ErrInvalidInput)
205		}
206	
207		var saved OverlapNote
208		err := svc.store.mutate(func(d *Data) error {
209			sa, _ := findShift(d, clean(shiftA))
210			sb, _ := findShift(d, clean(shiftB))
211			if sa == nil || sb == nil {
212				return fmt.Errorf("%w：班次 %s 或 %s 不存在", ErrNotFound, shiftA, shiftB)
213			}
214			if sa.Position != sb.Position {
215				return fmt.Errorf("%w：班次 %s（%s）与 %s（%s）岗位不同，无需重叠说明",
216					ErrPositionMismatch, sa.ID, sa.Position, sb.ID, sb.Position)
217			}
218			if !intervalsOverlap(sa.Start, sa.End, sb.Start, sb.End) {
219				return fmt.Errorf("%w：班次 %s 与 %s 的时间区间不重叠（端点相接不算重叠）",
220					ErrInvalidInput, sa.ID, sb.ID)
221			}
222			d.NoteSeq++
223			x, y := notePair(sa.ID, sb.ID)
224			saved = OverlapNote{
225				ID:        fmt.Sprintf("N%03d", d.NoteSeq),
226				Position:  sa.Position,
227				ShiftA:    x,
228				ShiftB:    y,
229				Note:      note,
230				CreatedAt: svc.now(),
231			}
232			d.Notes = append(d.Notes, saved)
233			return nil
234		})
235		return saved, err
236	}
237	
238	// AddItem 向未结束班次新增事项。内容、严重程度、后续负责人必填，限制条件可空。
239	func (svc *Service) AddItem(shiftID, content string, severity Severity, constraints, followOwner string) (Item, error) {
240		shiftID = clean(shiftID)
241		content = clean(content)
242		constraints = clean(constraints)
243		followOwner = clean(followOwner)
244		if err := requireNonEmpty("事项内容", content); err != nil {
245			return Item{}, err
246		}
247		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
248			return Item{}, err
249		}
250		if !severity.valid() {
251			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
252		}
253	
254		var created Item
255		err := svc.store.mutate(func(d *Data) error {
256			sh, _ := findShift(d, shiftID)
257			if sh == nil {
258				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
259			}
260			if sh.Closed {
261				return fmt.Errorf("%w：班次 %s 已结束，不能新增事项", ErrShiftClosed, sh.ID)
262			}
263			d.ItemSeq++
264			now := svc.now()
265			created = Item{
266				ID:             fmt.Sprintf("I%03d", d.ItemSeq),
267				OriginShiftID:  sh.ID,
268				ShiftIDs:       []string{sh.ID},
269				CurrentShiftID: sh.ID,
270				Content:        content,
271				Severity:       severity,
272				Constraints:    constraints,
273				FollowOwner:    followOwner,
274				CreatedAt:      now,
275				Events: []ItemEvent{
276					{At: now, Kind: "created", Detail: "事项建立"},
277				},
278			}
279			d.Items = append(d.Items, created)
280			return nil
281		})
282		if err != nil {
283			return Item{}, err
284		}
285		// 返回独立副本：调用方保留的新增结果与系统保存的事项脱离，
286		// 改动结果不影响存储，也不会在后续正常保存时被带进存储。
287		return cloneItem(created), nil
288	}
289	
290	// UpdateItem 在事项所在班次结束前修改其内容、严重程度、限制条件和后续负责人。
291	// 只有本地数据保存成功才算修改完成：写盘失败时内存变更随快照一并回滚，
292	// 返回错误与零值事项，不把尚未保存的新值当作修改结果。
293	func (svc *Service) UpdateItem(itemID, content string, severity Severity, constraints, followOwner string) (Item, error) {
294		itemID = clean(itemID)
295		content = clean(content)
296		constraints = clean(constraints)
297		followOwner = clean(followOwner)
298		if err := requireNonEmpty("事项内容", content); err != nil {
299			return Item{}, err
300		}
301		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
302			return Item{}, err
303		}
304		if !severity.valid() {
305			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
306		}
307	
308		var updated Item
309		err := svc.store.mutate(func(d *Data) error {
310			it, _ := findItem(d, itemID)
311			if it == nil {
312				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
313			}
314			sh, _ := findShift(d, it.CurrentShiftID)
315			if sh == nil || sh.Closed {
316				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，内容不能修改",
317					ErrShiftClosed, itemID, it.CurrentShiftID)
318			}
319			changes := []string{}
320			if it.Content != content {
321				changes = append(changes, "内容")
322			}
323			if it.Severity != severity {
324				changes = append(changes, "严重程度")
325			}
326			if it.Constraints != constraints {
327				changes = append(changes, "限制条件")
328			}
329			if it.FollowOwner != followOwner {
330				changes = append(changes, "后续负责人")
331			}
332			it.Content = content
333			it.Severity = severity
334			it.Constraints = constraints
335			it.FollowOwner = followOwner
336			it.Events = append(it.Events, ItemEvent{
337				At:     svc.now(),
338				Kind:   "updated",
339				Detail: "修改字段：" + joinOr(changes, "无变更"),
340			})
341			updated = *it
342			return nil
343		})
344		if err != nil {
345			// 保存失败时内存已回滚，不能把尚未保存的新值当作修改结果返回。
346			return Item{}, err
347		}
348		// 返回独立副本：调用方保留的修改结果不与系统保存的事项共享内存。
349		return cloneItem(updated), nil
350	}
351	
352	func joinOr(xs []string, or string) string {
353		if len(xs) == 0 {
354			return or
355		}
356		return strings.Join(xs, "、")
357	}
358	
359	// CloseItem 在事项所在班次结束前关闭该事项，须填写操作人。
360	// 只有本地数据保存成功才算关闭完成：写盘失败时内存变更随快照一并回滚，
361	// 返回错误与零值事项，不把尚未保存的关闭状态当作关闭结果。
362	func (svc *Service) CloseItem(itemID, operator string) (Item, error) {
363		itemID = clean(itemID)
364		operator = clean(operator)
365		if err := requireNonEmpty("操作人", operator); err != nil {
366			return Item{}, err
367		}
368	
369		var closed Item
370		err := svc.store.mutate(func(d *Data) error {
371			it, _ := findItem(d, itemID)
372			if it == nil {
373				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
374			}
375			if it.Closed {
376				return fmt.Errorf("%w：事项 %s 已关闭，不能重复关闭", ErrHandoverState, itemID)
377			}
378			sh, _ := findShift(d, it.CurrentShiftID)
379			if sh == nil || sh.Closed {
380				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，关闭状态不能修改",
381					ErrShiftClosed, itemID, it.CurrentShiftID)
382			}
383			now := svc.now()
384			it.Closed = true
385			it.ClosedAt = &now
386			it.CloseOperator = operator
387			it.Events = append(it.Events, ItemEvent{At: now, Kind: "closed", Operator: operator})
388			closed = *it
389			return nil
390		})
391		if err != nil {
392			// 保存失败时内存已回滚，不能把尚未保存的关闭状态当作关闭结果返回。
393			return Item{}, err
394		}
395		// 返回独立副本：调用方保留的关闭结果（含关闭时间）与系统保存的事项脱离；
396		// 班次结束后再改写这份结果中的关闭时刻，结束时记录里保留的仍是当时的值。
397		return cloneItem(closed), nil
398	}
399	
400	// CloseShift 结束班次。任一接班交接存在未确认接收的事项（待处理、退回、
401	// 处理结果缺失或无法识别）时不允许结束，其他交接已完成也不能放行；空清单
402	// 交接视为已完成，可以结束。
403	// 结束成功时把在班事项（本班新增与已接收，含结束前已关闭者）冻结为结束时记录；
404	// 校验或保存失败时不留下任何记录，班次保持进行中，也不改变交接结果、
405	// 事项归属与已保存的处理经过。
406	// 只有本地数据保存成功才算结束完成：写盘失败时内存变更随快照一并回滚，
407	// 保留原保存错误并返回零值班次（无编号、无结束状态、无结束时间、无结束时
408	// 事项记录，空清单班次同样如此），不把尚未保存的结束状态或失败前查询到的
409	// 进行中班次当作结束结果返回。
410	// 返回的班次结果是成功结束时的独立副本（关闭时间与结束时记录均深拷贝）：
411	// 调用方为本地展示改动结果（实际结束时刻、事项内容、清单项、关闭时间等）
412	// 只影响手中的结果，不改变系统保存的结束时事实，也不随之后的正常保存被带进
413	// 存储；先取得的另一份结果同样互不影响。
414	func (svc *Service) CloseShift(shiftID string) (Shift, error) {
415		shiftID = clean(shiftID)
416		var result Shift
417		err := svc.store.mutate(func(d *Data) error {
418			sh, _ := findShift(d, shiftID)
419			if sh == nil {
420				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
421			}
422			if sh.Closed {
423				return fmt.Errorf("%w：班次 %s 已结束", ErrShiftClosed, sh.ID)
424			}
425			for i := range d.Handovers {
426				h := &d.Handovers[i]
427				if h.ToShiftID == sh.ID && !h.Completed() {
428					return fmt.Errorf("%w：接班交接 %s 仍有未确认接收的事项，班次不能结束",
429						ErrHandoverState, h.ID)
430				}
431			}
432			now := svc.now()
433			sh.Closed = true
434			sh.ClosedAt = &now
435	
436			// 冻结结束时在班的全部事项。退回或未确认的交接事项当前班次仍在交班
437			// 班次，不会被快照；结束前已关闭的事项保留关闭人与关闭时间。每项指针
438			// （关闭时间）都复制一份：结束时记录保留这次成功结束时的事实，既不与
439			// 事项当前记录共享内存，也不与交给调用方的结果共享内存。
440			record := &ShiftCloseRecord{Items: []CloseItemSnapshot{}}
441			for i := range d.Items {
442				it := &d.Items[i]
443				if it.CurrentShiftID != sh.ID {
444					continue
445				}
446				record.Items = append(record.Items, CloseItemSnapshot{
447					ItemID:        it.ID,
448					Content:       it.Content,
449					Severity:      it.Severity,
450					Constraints:   it.Constraints,
451					FollowOwner:   it.FollowOwner,
452					Closed:        it.Closed,
453					ClosedAt:      cloneTimePtr(it.ClosedAt),
454					CloseOperator: it.CloseOperator,
455				})
456			}
457			sort.Slice(record.Items, func(i, j int) bool { return record.Items[i].ItemID < record.Items[j].ItemID })
458			sh.CloseRecord = record
459	
460			// 返回独立副本：调用方改写自己保留的结果不能影响系统保存的结束时记录。
461			result = cloneShift(*sh)
462			return nil
463		})
464		if err != nil {
465			// 业务拒绝或保存失败时不返回任何班次结果：保存失败时内存已回滚，
466			// 不能把尚未保存的结束状态当作结束结果交给调用方。
467			return Shift{}, err
468		}
469		return result, nil
470	}
471	
472	// CreateHandover 由交班班次向同岗位接班班次发起交接。
473	// 重复向同一接班班次发起返回已有记录（ErrHandoverExists）；该承诺在接班班次
474	// 随后结束、事项已在后续班次关闭或继续流转后仍然成立，返回保存的原交接内容，
475	// 不重新挑选清单、不重新接收或移动事项、不追加经过。改换接班对象报
476	// ErrHandoverTarget 并指出原接班班次，无论新对象是否结束都不产生第二条交接。
477	// 不存在的班次编号与交给自身始终按各自错误拒绝；同岗位及接班班次尚未结束等
478	// 要求仅对首次发起生效。
479	// 只有本地数据保存成功才算发起完成：首次发起的输入与班次状态均合法、实际进入
480	// 保存阶段后写盘失败时，内存变更随快照一并回滚，返回原保存错误与零值交接结果
481	// （编号、岗位、两班编号为空，发起时间为零值，完成时间为空，清单没有事项），
482	// 不把尚未保存的编号、发起时间、清单或空清单的完成时间当作发起结果；失败尝试
483	// 不占用交接编号，也不留下已指定接班对象的关系。
484	func (svc *Service) CreateHandover(fromShiftID, toShiftID string) (Handover, error) {
485		fromShiftID = clean(fromShiftID)
486		toShiftID = clean(toShiftID)
487	
488		var result Handover
489		// saved 标记业务变更是否已完整执行、只待落盘：此后出现的错误只能是保存
490		// 阶段失败，而不是业务拒绝。
491		saved := false
492		err := svc.store.mutate(func(d *Data) error {
493			from, _ := findShift(d, fromShiftID)
494			to, _ := findShift(d, toShiftID)
495			if from == nil {
496				return fmt.Errorf("%w：交班班次 %s", ErrNotFound, fromShiftID)
497			}
498			if to == nil {
499				return fmt.Errorf("%w：接班班次 %s", ErrNotFound, toShiftID)
500			}
501			if from.ID == to.ID {
502				return fmt.Errorf("%w：交班班次与接班班次不能都是 %s", ErrSameShift, from.ID)
503			}
504			// 同一交班班次只能指定一个接班对象。重复发起（包括接班班次随后已
505			// 结束、事项已在后续班次关闭或继续流转的情况）一律返回保存的原记录，
506			// 不重新接收事项、不追加经过；改换为另一个确实存在的接班对象（无论其
507			// 是否结束、是否同岗位）都按改换对象报错并指出原接班班次，且不能生成
508			// 第二条交接。该判定先于同岗位、接班班次状态等首次发起校验；编号不
509			// 存在与交给自身的校验仍在其前。
510			for i := range d.Handovers {
511				if d.Handovers[i].FromShiftID == from.ID {
512					existing := &d.Handovers[i]
513					// 即使以“已存在”错误返回，交出的也是独立副本，调用方改动
514					// 不影响系统保存的原交接记录。
515					result = cloneHandover(*existing)
516					if existing.ToShiftID != to.ID {
517						return fmt.Errorf("%w：交班班次 %s 已指定接班班次 %s，不能改换为 %s",
518							ErrHandoverTarget, from.ID, existing.ToShiftID, to.ID)
519					}
520					return fmt.Errorf("%w：交接 %s", ErrHandoverExists, existing.ID)
521				}
522			}
523	
524			if from.Position != to.Position {
525				return fmt.Errorf("%w：班次 %s（%s）不能交给其他岗位 %s（%s）",
526					ErrPositionMismatch, from.ID, from.Position, to.ID, to.Position)
527			}
528	
529			// 以下为首次发起的要求：接班班次尚未结束、开始时间不早于交班班次、
530			// 交班班次已经结束，重叠区间须有有效说明（正文去掉首尾空白后仍有内容，
531			// 只凭说明记录存在不算）。
532			if to.Closed {
533				return fmt.Errorf("%w：接班班次 %s 已结束，不能交接", ErrShiftClosed, to.ID)
534			}
535			if to.Start.Before(from.Start) {
536				return fmt.Errorf("%w：接班班次 %s 开始时间 %s 早于交班班次 %s 开始时间 %s",
537					ErrInvalidInput, to.ID, to.Start.Format(time.RFC3339),
538					from.ID, from.Start.Format(time.RFC3339))
539			}
540			if !from.Closed {
541				return fmt.Errorf("%w：交班班次 %s 尚未结束，结束班次后未关闭事项才成为交接清单",
542					ErrShiftNotClosed, from.ID)
543			}
544			if intervalsOverlap(from.Start, from.End, to.Start, to.End) && !hasEffectiveNote(d, from.ID, to.ID) {
545				return fmt.Errorf("%w：交班班次 %s 与接班班次 %s 时间区间重叠，须先填写重叠说明",
546					ErrOverlap, from.ID, to.ID)
547			}
548	
549			entries := []HandoverEntry{}
550			for i := range d.Items {
551				it := &d.Items[i]
552				if it.CurrentShiftID == from.ID && !it.Closed {
553					entries = append(entries, HandoverEntry{
554						ItemID:      it.ID,
555						Content:     it.Content,
556						Severity:    it.Severity,
557						Constraints: it.Constraints,
558						FollowOwner: it.FollowOwner,
559						Status:      EntryPending,
560					})
561				}
562			}
563			sort.Slice(entries, func(i, j int) bool { return entries[i].ItemID < entries[j].ItemID })
564	
565			d.HandoverSeq++
566			now := svc.now()
567			h := Handover{
568				ID:          fmt.Sprintf("H%03d", d.HandoverSeq),
569				Position:    from.Position,
570				FromShiftID: from.ID,
571				ToShiftID:   to.ID,
572				CreatedAt:   now,
573				Entries:     entries,
574			}
575			if len(entries) == 0 {
576				// 空清单直接完成。
577				h.CompletedAt = &now
578			}
579			d.Handovers = append(d.Handovers, h)
580			result = cloneHandover(h)
581			saved = true
582			return nil
583		})
584		if err != nil {
585			if saved {
586				// 业务校验全部通过、实际进入保存阶段后失败：内存已随快照回滚，
587				// 不能把尚未保存的新交接（编号、发起时间、清单与空清单的完成时间）
588				// 当作发起结果交给调用方。
589				return Handover{}, err
590			}
591			// 业务拒绝：重复发起与改换对象仍按承诺返回保存的原记录。
592			return result, err
593		}
594		return result, nil
595	}
