597	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
598	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
599	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
600	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
601	// 最后一项成功接收使整份交接首次全部明确接收时，完成时间记为本次成功处理时间；
602	// 若记录里存在补齐前误写（或零值）的旧完成时间，一并以本次时间覆盖。本次处理失败、
603	// 退回或仍有未接收项时不写完成时间，交接不能提前完成。
604	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
605		handoverID = clean(handoverID)
606		itemID = clean(itemID)
607		operator = clean(operator)
608		reason = clean(reason)
609		trackingNote = clean(trackingNote)
610		nextFollowOwner = clean(nextFollowOwner)
611	
612		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
613			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
614		}
615		if err := requireNonEmpty("操作人", operator); err != nil {
616			return Handover{}, err
617		}
618	
619		var result Handover
620		err := svc.store.mutate(func(d *Data) error {
621			h, _ := findHandover(d, handoverID)
622			if h == nil {
623				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
624			}
625			e, _ := findEntry(h, itemID)
626			if e == nil {
627				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
628			}
629			if e.Status.Received() {
630				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
631					ErrHandoverState, e.ItemID, e.Status.Label())
632			}
633			if e.Status == EntryReturned {
634				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
635				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
636				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
637				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
638					ErrHandoverState, e.ItemID, h.ID)
639			}
640			switch action {
641			case ActionReturn:
642				if err := requireNonEmpty("退回原因", reason); err != nil {
643					return err
644				}
645			case ActionTrack:
646				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
647					return err
648				}
649				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
650					return err
651				}
652			}
653	
654			now := svc.now()
655			switch action {
656			case ActionConfirm:
657				e.Status = EntryConfirmed
658			case ActionTrack:
659				e.Status = EntryTracking
660				e.TrackingNote = trackingNote
661				e.FollowOwner = nextFollowOwner
662			case ActionReturn:
663				e.Status = EntryReturned
664				e.Rounds = append(e.Rounds, ReturnRound{
665					Seq:            len(e.Rounds) + 1,
666					ReturnedAt:     now,
667					ReturnOperator: operator,
668					Reason:         reason,
669				})
670			}
671			e.Operator = operator
672			e.ProcessedAt = &now
673	
674			if action != ActionReturn {
675				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
676				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
677					it.CurrentShiftID = h.ToShiftID
678					if !contains(it.ShiftIDs, h.ToShiftID) {
679						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
680					}
681					detail := receivedDetailText(h, action, e.Status.Label(), trackingNote, nextFollowOwner)
682					if action == ActionTrack {
683						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
684						it.FollowOwner = nextFollowOwner
685					}
686					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
687				}
688			}
689	
690			if h.Completed() {
691				// 完成时间记录这份交接真正接收齐全部事项的时刻：以最后一次成功
692				// 接收（确认或继续跟踪）的处理时间为准。旧数据可能在清单仍有结果
693				// 缺失、无法识别、待处理或退回项时就误写过完成时间（或只留下零值）：
694				// 接班人逐项补齐、整份交接首次全部明确接收时，用本次成功处理时间
695				// 覆盖那个旧时间，不能沿用补齐前的时刻；旧时间缺失（nil）时同样在
696				// 本次补上。未全部接收（如本次退回、仍有异常结果项）时不写入，
697				// 交接保持未完成。正常流程与空清单在首次全部接收时写入，之后已接收
698				// 项无法再处理，完成时间不会被改写。
699				h.CompletedAt = &now
700			}
701			// 返回独立副本：调用方保留的处理结果（含逐项处理时间、退回/补充记录
702			// 与完成时间）不与系统保存的交接共享内存。
703			result = cloneHandover(*h)
704			return nil
705		})
706		return result, err
707	}
708	
709	// validProcessedAt 报告处理时间是否真实记录：nil 或零值
710	// （0001-01-01T00:00:00Z）都视为未记录，不推测补齐。
711	func validProcessedAt(t *time.Time) bool { return t != nil && !t.IsZero() }
712	
713	func contains(xs []string, x string) bool {
714		for _, v := range xs {
715			if v == x {
716				return true
717			}
718		}
719		return false
720	}
721	
722	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
723	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
724	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
725	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
726	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
727	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
728	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
729		handoverID = clean(handoverID)
730		itemID = clean(itemID)
731		operator = clean(operator)
732		supplement = clean(supplement)
733		if err := requireNonEmpty("操作人", operator); err != nil {
734			return Handover{}, err
735		}
736		if err := requireNonEmpty("补充说明", supplement); err != nil {
737			return Handover{}, err
738		}
739	
740		var result Handover
741		err := svc.store.mutate(func(d *Data) error {
742			h, _ := findHandover(d, handoverID)
743			if h == nil {
744				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
745			}
746			e, _ := findEntry(h, itemID)
747			if e == nil {
748				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
749			}
750			if e.Status != EntryReturned {
751				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
752					ErrHandoverState, e.ItemID, e.Status.Label())
753			}
754			if len(e.Rounds) == 0 {
755				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
756			}
757			round := &e.Rounds[len(e.Rounds)-1]
758			if round.ResubmittedAt != nil {
759				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
760			}
761			now := svc.now()
762			round.Supplement = supplement
763			round.SupplementOperator = operator
764			round.SupplementAt = &now
765			round.ResubmittedAt = &now
766			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
767			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
768			e.Status = EntryPending
769			e.Operator = ""
770			e.ProcessedAt = nil
771			// 返回独立副本：调用方保留的重新提交结果不与系统保存的交接共享内存。
772			result = cloneHandover(*h)
773			return nil
774		})
775		return result, err
776	}
