840	// cloneTimePtr 复制时间指针，nil 保持 nil。
841	func cloneTimePtr(t *time.Time) *time.Time {
842		if t == nil {
843			return nil
844		}
845		v := *t
846		return &v
847	}
848	
849	// cloneItem 深拷贝事项：流经班次、历史事件与关闭时间都与存储中的记录脱离。
850	func cloneItem(it Item) Item {
851		out := it
852		out.ShiftIDs = append([]string(nil), it.ShiftIDs...)
853		out.Events = append([]ItemEvent(nil), it.Events...)
854		out.ClosedAt = cloneTimePtr(it.ClosedAt)
855		return out
856	}
