858	// cloneCloseItemSnapshot 深拷贝结束时事项快照（含关闭时间指针）。
859	func cloneCloseItemSnapshot(s CloseItemSnapshot) CloseItemSnapshot {
860		out := s
861		out.ClosedAt = cloneTimePtr(s.ClosedAt)
862		return out
863	}
