865	// cloneCloseRecord 深拷贝班次结束时记录；nil 保持 nil，
866	// 空清单仍是非 nil 记录，与缺少结束时记录的旧数据相区别。
867	func cloneCloseRecord(rec *ShiftCloseRecord) *ShiftCloseRecord {
868		if rec == nil {
869			return nil
870		}
871		out := &ShiftCloseRecord{}
872		if rec.Items != nil {
873			out.Items = make([]CloseItemSnapshot, len(rec.Items))
874			for i, s := range rec.Items {
875				out.Items[i] = cloneCloseItemSnapshot(s)
876			}
877		}
878		return out
879	}
