889	// cloneEntry 深拷贝交接单项：处理时间与历次退回/补充记录都与存储中的记录脱离。
890	func cloneEntry(e HandoverEntry) HandoverEntry {
891		out := e
892		out.ProcessedAt = cloneTimePtr(e.ProcessedAt)
893		if e.Rounds != nil {
894			out.Rounds = make([]ReturnRound, len(e.Rounds))
895			for i, r := range e.Rounds {
896				out.Rounds[i] = r
897				out.Rounds[i].SupplementAt = cloneTimePtr(r.SupplementAt)
898				out.Rounds[i].ResubmittedAt = cloneTimePtr(r.ResubmittedAt)
899			}
900		}
901		return out
902	}
903	
904	// cloneHandover 深拷贝交接记录：完成时间与清单各项都与存储中的记录脱离。
905	func cloneHandover(h Handover) Handover {
906		out := h
907		out.CompletedAt = cloneTimePtr(h.CompletedAt)
908		if h.Entries != nil {
909			out.Entries = make([]HandoverEntry, len(h.Entries))
910			for i, e := range h.Entries {
911				out.Entries[i] = cloneEntry(e)
912			}
913		}
914		return out
915	}
916	
917	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
918	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
919	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
920	// 返回的报告是查询当时的独立副本：班次信息、事项清单、结束时记录、最新状态
921	// 对照、关联交接与各项结果（含关闭时间、处理时间与历次退回补充记录）全部深拷贝，
922	// 调用方改动报告不影响系统保存的数据与其他已取得的报告，系统随后的正常处理
923	// 也不会改写这份报告；再次查询才反映最新内容。
924	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
925		shiftID = clean(shiftID)
926		d := &svc.store.data
927		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
928		sh, _ := findShift(d, shiftID)
929		if sh == nil {
930			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
931		}
932		rep.Shift = cloneShift(*sh)
933	
934		for _, n := range d.Notes {
935			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
936				rep.OverlapNotes = append(rep.OverlapNotes, n)
937			}
938		}
939		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
940	
941		switch {
942		case !sh.Closed:
943			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
944			rep.Items = currentItemsOfShift(d, sh.ID)
945		case sh.CloseRecord != nil:
946			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
947			rep.ItemsAtClose = true
948			rep.CloseItems = make([]CloseItemSnapshot, len(sh.CloseRecord.Items))
949			for i, s := range sh.CloseRecord.Items {
950				rep.CloseItems[i] = cloneCloseItemSnapshot(s)
951			}
952			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
953			for _, s := range rep.CloseItems {
954				if it, _ := findItem(d, s.ItemID); it != nil {
955					rep.LatestItems[s.ItemID] = cloneItem(*it)
956				}
957			}
958		default:
959			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
960			rep.HistoryIncomplete = true
961			rep.Items = currentItemsOfShift(d, sh.ID)
962		}
963		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
964		for i := range rep.Items {
965			rep.Items[i] = cloneItem(rep.Items[i])
966		}
967	
968		for i := range d.Handovers {
969			h := &d.Handovers[i]
970			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
971			if !involved {
972				continue
973			}
974			if h.FromShiftID == sh.ID {
975				cp := cloneHandover(*h)
976				rep.Outgoing = &cp
977			}
978			if h.ToShiftID == sh.ID {
979				rep.Incoming = append(rep.Incoming, cloneHandover(*h))
980			}
981			for j := range h.Entries {
982				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
983					HandoverID: h.ID,
984					FromShift:  h.FromShiftID,
985					ToShift:    h.ToShiftID,
986					Entry:      cloneEntry(h.Entries[j]),
987				})
988			}
989		}
990		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
991		for k := range rep.Results {
992			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
993		}
994		return rep, nil
995	}
996

