184		}
185	
186		// 退出后重新打开：交接进度、事项所在班次和后续负责人与失败前一致。
187		f.reopen(t)
188		assertLastItemStillPending(t, f, h.ID, a.ID, b.ID, idLast, idFirst, confirmAt)
189	
190		// 保存条件恢复后，对同一项再次提交继续跟踪：按现有功能成功接收。
191		restoreSaving(t, f)
192		successAt := tsDay(2, 19, 0)
193		f.svc.nowAt(func() time.Time { return successAt })
194		if _, err := f.svc.ProcessEntry(h.ID, idLast, ActionTrack, "李四", "", "持续跟踪压力变化", "王五"); err != nil {
195			t.Fatalf("恢复后继续跟踪应成功：%v", err)
196		}
197	
198		// 交接：最后一项只成功接收这一次，处理人与处理时间反映成功操作，
199		// 整份交接的完成时间以这次成功处理为准。
200		h2, err := f.svc.GetHandover(h.ID)
201		if err != nil {
202			t.Fatalf("get handover after retry: %v", err)
203		}
204		if !h2.Completed() || h2.CompletedAt == nil || !h2.CompletedAt.Equal(successAt) {
205			t.Fatalf("完成时间应以成功处理时刻 19:00 为准：%+v", h2)
206		}
207		le := findEntryOf(t, h2, idLast)
208		if le.Status != EntryTracking || le.Operator != "李四" || le.ProcessedAt == nil ||
209			!le.ProcessedAt.Equal(successAt) || le.TrackingNote != "持续跟踪压力变化" ||
210			le.FollowOwner != "王五" {
