package handover

import (
	"errors"
	"os"
	"strings"
	"testing"
	"time"
)

// breakSaving 在数据文件的临时写入路径上放一个目录，使 commit 的临时文件
// 写入必然失败（EISDIR）。这是“真正进入保存过程后”的失败：业务校验已全部
// 通过、内存变更已经发生，失败点在原子写盘阶段；与是否以 root 运行无关，
// 因而测试可在任意机器上独立重复。
func breakSaving(t *testing.T, f *fixture) {
	t.Helper()
	tmp := f.store.Path() + ".tmp"
	if err := os.Mkdir(tmp, 0o755); err != nil {
		t.Fatalf("制造保存失败：%v", err)
	}
}

// restoreSaving 移除故障路径，使保存恢复正常。
func restoreSaving(t *testing.T, f *fixture) {
	t.Helper()
	if err := os.RemoveAll(f.store.Path() + ".tmp"); err != nil {
		t.Fatalf("恢复保存：%v", err)
	}
}

// assertLastItemStillPending 用当前打开的数据核对：失败的继续跟踪没有留下
// 任何半完成结果。
func assertLastItemStillPending(t *testing.T, f *fixture, hID, fromShift, toShift, lastID, otherID string, otherProcessedAt time.Time) {
	t.Helper()

	// 交接：最后一项仍为待处理，当前处理人与处理时间显示尚未处理，没有本次
	// 跟踪说明或新负责人，也没有退回轮次；整份交接未完成且无完成时间。
	h, err := f.svc.GetHandover(hID)
	if err != nil {
		t.Fatalf("get handover: %v", err)
	}
	if h.Completed() || h.CompletedAt != nil {
		t.Fatalf("保存失败后整份交接应继续未完成、不能留下完成时间：%+v", h)
	}
	e := findEntryOf(t, h, lastID)
	if e.Status != EntryPending {
		t.Fatalf("最后一项应仍为待处理，got %s", e.Status)
	}
	if e.Operator != "" || e.ProcessedAt != nil {
		t.Fatalf("最后一项的当前处理人与处理时间应仍为尚未处理：%+v", e)
	}
	if e.TrackingNote != "" || e.FollowOwner != "李四" {
		t.Fatalf("不应留下本次跟踪说明或新负责人：%+v", e)
	}
	if len(e.Rounds) != 0 {
		t.Fatalf("失败尝试不应产生退回/补充经过：%+v", e.Rounds)
	}
	// 之前已经接收的其他事项及其处理信息保持原样。
	oe := findEntryOf(t, h, otherID)
	if oe.Status != EntryConfirmed || oe.Operator != "李四" ||
		oe.ProcessedAt == nil || !oe.ProcessedAt.Equal(otherProcessedAt) {
		t.Fatalf("已接收的其他事项处理信息应保持原样：%+v", oe)
	}

	// 事项：仍留在交班班次，流经班次不增加接班班次，负责人不变，
	// 事项历史不增加这次接收。
	it, err := f.svc.GetItem(lastID)
	if err != nil {
		t.Fatalf("get item: %v", err)
	}
	if it.CurrentShiftID != fromShift {
		t.Fatalf("事项应仍留在交班班次 %s，got %s", fromShift, it.CurrentShiftID)
	}
	if len(it.ShiftIDs) != 1 || it.ShiftIDs[0] != fromShift {
		t.Fatalf("流经班次不应增加接班班次：%v", it.ShiftIDs)
	}
	if it.FollowOwner != "李四" {
		t.Fatalf("事项后续负责人应保持原值，got %s", it.FollowOwner)
	}
	for _, ev := range it.Events {
		if ev.Kind == "received" || strings.Contains(ev.Detail, "接班班次") {
			t.Fatalf("事项处理经过不应增加这次失败的接收：%+v", ev)
		}
	}

	// 处理经过查询同样不出现这次接收，交接当前结果仍为待处理。
	j, err := f.svc.ItemJourney(lastID)
	if err != nil {
		t.Fatalf("journey: %v", err)
	}
	if len(j.Results) != 1 || j.Results[0].Entry.Status != EntryPending {
		t.Fatalf("处理经过中的交接当前结果应仍为待处理：%+v", j.Results)
	}
	for _, ev := range j.Events {
		if ev.Kind == "track" || ev.Kind == "received" {
			t.Fatalf("处理经过不应出现失败的继续跟踪接收：%+v", ev)
		}
		if ev.TrackingNote != "" {
			t.Fatalf("处理经过不应留下失败尝试的跟踪说明：%+v", ev)
		}
	}

	// 交班班次的结束时事项记录保留原来的内容与负责人。
	rep, err := f.svc.ShiftReport(fromShift)
	if err != nil {
		t.Fatalf("report from shift: %v", err)
	}
	snap := findCloseItem(rep, lastID)
	if snap == nil || snap.FollowOwner != "李四" || snap.Content != "事项乙" {
		t.Fatalf("交班班次结束时记录应保持原内容与负责人：%+v", snap)
	}

	// 展示层与保存事实一致：未完成、尚未处理、无本次跟踪说明。
	text := FormatHandover(h)
	if !strings.Contains(text, "[未完成]") {
		t.Fatalf("交接应显示未完成：\n%s", text)
	}
	if !strings.Contains(text, "处理人=尚未处理；处理时间=尚未处理") {
		t.Fatalf("待处理项应显示尚未处理：\n%s", text)
	}
	if strings.Contains(text, "持续跟踪压力变化") || strings.Contains(text, "王五") {
		t.Fatalf("失败的跟踪说明与新负责人不应出现在交接查询中：\n%s", text)
	}
}

// TestTrackSaveFailureAtomicRollback：接班人对最后一项待处理事项选择继续跟踪，
// 参数合法、状态允许、真正进入保存过程后本地写盘失败——操作必须明确返回保存
// 错误，且交接、事项、班次与处理经过都不留下半完成结果；失败前已保存的数据
// （含交班班次结束时记录）原样保留，重新打开后一致。保存恢复后对同一项再次
// 提交，按现有功能成功接收，处理经过只留下成功的这一次。
func TestTrackSaveFailureAtomicRollback(t *testing.T) {
	f := newFixture(t)
	a, b, items := prepareHandover(t, f)
	h, err := f.svc.CreateHandover(a.ID, b.ID)
	if err != nil {
		t.Fatalf("create handover: %v", err)
	}
	idFirst, idLast := items[0].ID, items[1].ID // 事项甲、事项乙（事项丙已关闭）

	// 其中一项已经成功接收；最后一项仍待处理且属于交班班次。
	confirmAt := tsDay(2, 17, 0)
	f.svc.nowAt(func() time.Time { return confirmAt })
	if _, err := f.svc.ProcessEntry(h.ID, idFirst, ActionConfirm, "李四", "", "", ""); err != nil {
		t.Fatalf("confirm first: %v", err)
	}
	got, _ := f.svc.GetHandover(h.ID)
	if got.Completed() {
		t.Fatalf("前置：仍有一项待处理，交接不应完成")
	}

	// 记录失败前已落盘的文件内容，并固定失败尝试的处理时刻。
	rawBefore, err := os.ReadFile(f.store.Path())
	if err != nil {
		t.Fatalf("read data file: %v", err)
	}
	failAt := tsDay(2, 18, 0)
	f.svc.nowAt(func() time.Time { return failAt })

	// 使下一次写盘在原子保存阶段失败。
	breakSaving(t, f)
	_, err = f.svc.ProcessEntry(h.ID, idLast, ActionTrack, "李四", "", "持续跟踪压力变化", "王五")
	// 操作必须明确返回错误，且这是保存错误而不是业务拒绝
	// （不能用缺少跟踪说明、负责人为空或事项已接收等来冒充）。
	if err == nil {
		t.Fatalf("保存失败时操作应返回错误")
	}
	if !strings.Contains(err.Error(), "写入数据文件失败") {
		t.Fatalf("应明确返回保存阶段的错误，got %v", err)
	}
	if errors.Is(err, ErrInvalidInput) || errors.Is(err, ErrHandoverState) || errors.Is(err, ErrNotFound) {
		t.Fatalf("参数合法、状态允许时的保存失败不应被报告为业务校验错误，got %v", err)
	}

	// 当前打开的数据中不留半完成结果。
	assertLastItemStillPending(t, f, h.ID, a.ID, b.ID, idLast, idFirst, confirmAt)

	// 失败前已保存的数据文件一个字节都不应改变（原子改名未发生）。
	rawAfter, err := os.ReadFile(f.store.Path())
	if err != nil {
		t.Fatalf("read data file after failure: %v", err)
	}
	if string(rawAfter) != string(rawBefore) {
		t.Fatalf("保存失败不得改动既有数据文件")
	}

	// 退出后重新打开：交接进度、事项所在班次和后续负责人与失败前一致。
	f.reopen(t)
	assertLastItemStillPending(t, f, h.ID, a.ID, b.ID, idLast, idFirst, confirmAt)

	// 保存条件恢复后，对同一项再次提交继续跟踪：按现有功能成功接收。
	restoreSaving(t, f)
	successAt := tsDay(2, 19, 0)
	f.svc.nowAt(func() time.Time { return successAt })
	if _, err := f.svc.ProcessEntry(h.ID, idLast, ActionTrack, "李四", "", "持续跟踪压力变化", "王五"); err != nil {
		t.Fatalf("恢复后继续跟踪应成功：%v", err)
	}

	// 交接：最后一项只成功接收这一次，处理人与处理时间反映成功操作，
	// 整份交接的完成时间以这次成功处理为准。
	h2, err := f.svc.GetHandover(h.ID)
	if err != nil {
		t.Fatalf("get handover after retry: %v", err)
	}
	if !h2.Completed() || h2.CompletedAt == nil || !h2.CompletedAt.Equal(successAt) {
		t.Fatalf("完成时间应以成功处理时刻 19:00 为准：%+v", h2)
	}
	le := findEntryOf(t, h2, idLast)
	if le.Status != EntryTracking || le.Operator != "李四" || le.ProcessedAt == nil ||
		!le.ProcessedAt.Equal(successAt) || le.TrackingNote != "持续跟踪压力变化" ||
		le.FollowOwner != "王五" {
		t.Fatalf("最后一项应为本次成功的继续跟踪：%+v", le)
	}
	if len(le.Rounds) != 0 {
		t.Fatalf("失败尝试不应变成历史事实（无退回轮次）：%+v", le.Rounds)
	}

	// 事项：保留编号进入接班班次，流经班次只含交班与接班两班，负责人与历史
	// 只反映成功的这一次接收。
	it, err := f.svc.GetItem(idLast)
	if err != nil {
		t.Fatalf("get item after retry: %v", err)
	}
	if it.ID != idLast || it.CurrentShiftID != b.ID {
		t.Fatalf("应保留事项编号并进入接班班次：%+v", it)
	}
	if len(it.ShiftIDs) != 2 || it.ShiftIDs[0] != a.ID || it.ShiftIDs[1] != b.ID {
		t.Fatalf("流经班次应只增加一次接班班次：%v", it.ShiftIDs)
	}
	if it.FollowOwner != "王五" {
		t.Fatalf("事项后续负责人应为本次填写的新负责人，got %s", it.FollowOwner)
	}
	kinds := []string{}
	received := 0
	for _, ev := range it.Events {
		kinds = append(kinds, ev.Kind)
		if ev.Kind == "received" {
			received++
			if !strings.Contains(ev.Detail, "持续跟踪压力变化") || ev.Operator != "李四" {
				t.Fatalf("接收记录应反映成功操作：%+v", ev)
			}
		}
	}
	if received != 1 || joinStrings(kinds) != "created,received" {
		t.Fatalf("事项历史只应留下成功的这一次接收，got %v", kinds)
	}

	// 处理经过：只展示成功的这一次继续跟踪，失败尝试不在任何事件中。
	j, err := f.svc.ItemJourney(idLast)
	if err != nil {
		t.Fatalf("journey after retry: %v", err)
	}
	if got := joinStrings(journeyKinds(j)); got != "created,handover-init,track" {
		t.Fatalf("处理经过应只留下成功的一次接收，got %s", got)
	}
	tracks := 0
	for _, ev := range j.Events {
		if ev.Kind == "track" {
			tracks++
			if !ev.TimeKnown || !ev.At.Equal(successAt) || ev.Operator != "李四" ||
				ev.TrackingNote != "持续跟踪压力变化" || ev.FollowOwner != "王五" {
				t.Fatalf("成功接收事件内容不正确：%+v", ev)
			}
		}
	}
	if tracks != 1 {
		t.Fatalf("应只有一次继续跟踪记录，got %d", tracks)
	}
	if len(j.Results) != 1 || j.Results[0].Entry.Status != EntryTracking {
		t.Fatalf("交接当前结果应为继续跟踪：%+v", j.Results)
	}

	// 重新打开后成功结果同样完整保留。
	f.reopen(t)
	h3, err := f.svc.GetHandover(h.ID)
	if err != nil {
		t.Fatalf("reopen get handover: %v", err)
	}
	if !h3.Completed() || h3.CompletedAt == nil || !h3.CompletedAt.Equal(successAt) {
		t.Fatalf("重开后交接完成状态与完成时间应保留：%+v", h3)
	}
	it3, err := f.svc.GetItem(idLast)
	if err != nil {
		t.Fatalf("reopen get item: %v", err)
	}
	if it3.CurrentShiftID != b.ID || it3.FollowOwner != "王五" {
		t.Fatalf("重开后事项所在班次与新负责人应保留：%+v", it3)
	}
	j3, err := f.svc.ItemJourney(idLast)
	if err != nil {
		t.Fatalf("reopen journey: %v", err)
	}
	if got := joinStrings(journeyKinds(j3)); got != "created,handover-init,track" {
		t.Fatalf("重开后处理经过应只保留成功的一次，got %s", got)
	}
}

// Command handover 是本地班次交接与未关闭事项的命令行入口。
//
// 数据默认保存在当前目录 handover-data.json，可用全局参数 --data 或环境变量
// HANDOVER_DATA 指定。时间统一使用带时区偏移的 RFC3339，如
// 2026-10-02T08:00:00+08:00。
package main

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"strings"
	"time"

	"github.com/bengzyyys/shift-handover/handover"
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

const usageText = `用法：handover [--data 文件] <命令> [参数]

数据持久化在本地 JSON 文件中，退出后重新打开数据仍在。
时间使用带时区的 RFC3339，例如 2026-10-02T08:00:00+08:00。

班次：
  shift-add      建立班次        --position 岗位 --owner 负责人 --start 开始 --end 结束
                                 [--note 重叠说明（与同岗位已存班次区间重叠时必填）]
  shift-list     列出全部班次
  shift-close    结束班次        --id 班次编号
  shift-show     按班次查询      --id 班次编号（完整事项/交接/结果）

重叠说明：
  note-add       为重叠班次填说明 --a 班次 --b 班次 --note 说明
  note-list      查看班次涉及的重叠说明 --id 班次

事项：
  item-add       新增事项        --shift 班次 --content 内容 \
                                 --severity normal|important|urgent \
                                 [--constraints 限制条件] --follow 后续负责人
  item-update    修改事项        --id 事项编号 --content 内容 \
                                 --severity normal|important|urgent \
                                 [--constraints 限制条件] --follow 后续负责人
  item-close     关闭事项        --id 事项编号 --operator 操作人
  item-show      查询事项        --id 事项编号（最新状态、完整处理经过与各次交接当前结果）

交接：
  handover-create   发起交接      --from 交班班次 --to 接班班次
  handover-list     列出全部交接
  handover-show     查看交接      --id 交接编号
  handover-process  接班人处理单项 --id 交接编号 --item 事项编号 \
                                 --action confirm|return|track --operator 操作人 \
                                 [--reason 退回原因] [--note 跟踪说明] [--follow 后续负责人]
  handover-resubmit 交班人补充并重新提交退回项 \
                                 --id 交接编号 --item 事项编号 \
                                 --operator 操作人 --supplement 补充说明
`

func run(argv []string, stdout, stderr io.Writer) int {
	args := append([]string(nil), argv...)
	dataPath, rest, err := splitDataFlag(args, os.Getenv("HANDOVER_DATA"))
	if err != nil {
		// 显式指定了数据文件却没给出有效路径：明确失败，不回落到
		// 环境变量或默认文件，也不展示帮助或任何业务数据。
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	if dataPath == "" {
		dataPath = "handover-data.json"
	}

	if len(rest) == 0 || rest[0] == "-h" || rest[0] == "--help" || rest[0] == "help" {
		fmt.Fprint(stdout, usageText)
		return 0
	}

	cmd, cmdArgs := rest[0], rest[1:]
	store, err := handover.Open(dataPath)
	if err != nil {
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	svc := handover.NewService(store)

	out, err := dispatch(svc, cmd, cmdArgs)
	if err != nil {
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	if out != "" {
		fmt.Fprint(stdout, out)
		if len(out) > 0 && out[len(out)-1] != '\n' {
			fmt.Fprintln(stdout)
		}
	}
	return 0
}

// valueFlags 是各子命令会带一个值的字符串参数。提取全局 --data 时，
// 这些参数后面的一个 token 是它的值：即使恰好写成 --data 或 --data=...，
// 也只是参数值（如事项内容、限制条件），不能当作数据文件参数取走。
var valueFlags = map[string]bool{
	"id": true, "position": true, "owner": true, "start": true, "end": true,
	"a": true, "b": true, "note": true, "shift": true, "content": true,
	"severity": true, "constraints": true, "follow": true, "operator": true,
	"from": true, "to": true, "item": true, "action": true, "reason": true,
	"supplement": true,
}

// splitDataFlag 从全部输入中抽出全局 --data（--data 路径 与 --data=路径 两种
// 形式，命令前后均可），返回数据文件路径与其余参数。已知参数的 --name value
// 形式中，value 原样保留，不参与 --data 判定；env 为未显式指定时的回退值。
// 显式给出 --data 却没有有效路径（--data 后为空字符串、--data= 后没有内容、
// 或命令末尾只有独立的 --data）时返回错误：这是输入错误，不能按未指定参数
// 回落到 env 或默认文件。
func splitDataFlag(args []string, env string) (dataPath string, rest []string, err error) {
	dataPath = env
	rest = make([]string, 0, len(args))
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if name, ok := flagName(arg); ok && name != "data" && valueFlags[name] {
			// 其他参数的 --name value 形式：下一个 token 是它的值，原样保留。
			rest = append(rest, arg)
			if i+1 < len(args) {
				rest = append(rest, args[i+1])
				i++
			}
			continue
		}
		switch {
		case arg == "--data":
			if i+1 >= len(args) {
				return "", nil, errors.New("--data 后缺少数据文件路径")
			}
			dataPath = args[i+1]
			i++
			if dataPath == "" {
				return "", nil, errors.New("--data 的数据文件路径不能为空")
			}
		case strings.HasPrefix(arg, "--data="):
			dataPath = arg[len("--data="):]
			if dataPath == "" {
				return "", nil, errors.New("--data 的数据文件路径不能为空")
			}
		default:
			rest = append(rest, arg)
		}
	}
	return dataPath, rest, nil
}

// flagName 解析 -name / --name 形式的参数名；带 = 的形式值已内联，返回 false。
func flagName(arg string) (string, bool) {
	if !strings.HasPrefix(arg, "-") || strings.Contains(arg, "=") {
		return "", false
	}
	name := strings.TrimLeft(arg, "-")
	return name, name != ""
}

func dispatch(svc *handover.Service, cmd string, args []string) (string, error) {
	fs := flag.NewFlagSet(cmd, flag.ContinueOnError)
	fs.SetOutput(io.Discard)

	var (
		id, position, owner, startS, endS              string
		a, b                                           string
		shift, content, severityS, constraints, follow string
		operator, from, to                             string
		item, actionS, reason, note, supplement        string
	)
	fs.StringVar(&id, "id", "", "记录编号")
	fs.StringVar(&position, "position", "", "岗位")
	fs.StringVar(&owner, "owner", "", "负责人")
	fs.StringVar(&startS, "start", "", "开始时间 RFC3339")
	fs.StringVar(&endS, "end", "", "结束时间 RFC3339")
	fs.StringVar(&a, "a", "", "班次编号 A")
	fs.StringVar(&b, "b", "", "班次编号 B")
	// note-add 时为重叠说明；handover-process --action track 时为跟踪说明。
	fs.StringVar(&note, "note", "", "重叠说明 / 跟踪说明")
	fs.StringVar(&shift, "shift", "", "班次编号")
	fs.StringVar(&content, "content", "", "事项内容")
	fs.StringVar(&severityS, "severity", "", "严重程度 normal|important|urgent")
	fs.StringVar(&constraints, "constraints", "", "限制条件（可空）")
	// follow 同时用于后续负责人（新增/修改事项）与跟踪后续负责人（track）。
	fs.StringVar(&follow, "follow", "", "后续负责人")
	fs.StringVar(&operator, "operator", "", "操作人")
	fs.StringVar(&from, "from", "", "交班班次编号")
	fs.StringVar(&to, "to", "", "接班班次编号")
	fs.StringVar(&item, "item", "", "事项编号")
	fs.StringVar(&actionS, "action", "", "confirm|return|track")
	fs.StringVar(&reason, "reason", "", "退回原因")
	fs.StringVar(&supplement, "supplement", "", "补充说明")
	if err := fs.Parse(args); err != nil {
		return "", err
	}

	switch cmd {
	case "shift-add":
		start, err := parseTime("--start", startS)
		if err != nil {
			return "", err
		}
		end, err := parseTime("--end", endS)
		if err != nil {
			return "", err
		}
		sh, err := svc.CreateShift(position, owner, start, end, note)
		if err != nil {
			return "", err
		}
		return "已建立班次 " + handover.FormatShift(sh), nil

	case "shift-list":
		shifts := svc.ListShifts()
		if len(shifts) == 0 {
			return "（暂无班次）", nil
		}
		out := ""
		for _, sh := range shifts {
			out += handover.FormatShift(sh) + "\n"
		}
		return out, nil

	case "shift-close":
		sh, err := svc.CloseShift(id)
		if err != nil {
			return "", err
		}
		return "已结束班次 " + handover.FormatShift(sh), nil

	case "shift-show":
		rep, err := svc.ShiftReport(id)
		if err != nil {
			return "", err
		}
		return handover.FormatReport(rep), nil

	case "note-add":
		n, err := svc.AddOverlapNote(a, b, note)
		if err != nil {
			return "", err
		}
		return "已保存重叠说明 " + handover.FormatOverlapNote(n), nil

	case "note-list":
		notes := svc.OverlapNotes(id)
		if len(notes) == 0 {
			return "（无重叠说明）", nil
		}
		out := ""
		for _, n := range notes {
			out += handover.FormatOverlapNote(n) + "\n\n"
		}
		return out, nil

	case "item-add":
		sev, err := handover.ParseSeverity(severityS)
		if err != nil {
			return "", err
		}
		it, err := svc.AddItem(shift, content, sev, constraints, follow)
		if err != nil {
			return "", err
		}
		return "已新增事项\n" + handover.FormatItem(it), nil

	case "item-update":
		sev, err := handover.ParseSeverity(severityS)
		if err != nil {
			return "", err
		}
		it, err := svc.UpdateItem(id, content, sev, constraints, follow)
		if err != nil {
			return "", err
		}
		return "已修改事项\n" + handover.FormatItem(it), nil

	case "item-close":
		it, err := svc.CloseItem(id, operator)
		if err != nil {
			return "", err
		}
		return "已关闭事项\n" + handover.FormatItem(it), nil

	case "item-show":
		j, err := svc.ItemJourney(id)
		if err != nil {
			return "", err
		}
		return handover.FormatItemJourney(j), nil

	case "handover-create":
		h, err := svc.CreateHandover(from, to)
		if err != nil {
			if errors.Is(err, handover.ErrHandoverExists) {
				// 重复发起返回已有记录，不视为失败。
				return "已存在交接记录（重复发起，返回已有记录）\n" + handover.FormatHandover(h), nil
			}
			return "", err
		}
		return "已发起交接\n" + handover.FormatHandover(h), nil

	case "handover-list":
		hs := svc.ListHandovers()
		if len(hs) == 0 {
			return "（暂无交接记录）", nil
		}
		out := ""
		for _, h := range hs {
			out += handover.FormatHandover(h) + "\n"
		}
		return out, nil

	case "handover-show":
		h, err := svc.GetHandover(id)
		if err != nil {
			return "", err
		}
		return handover.FormatHandover(h), nil

	case "handover-process":
		action, err := handover.ParseAction(actionS)
		if err != nil {
			return "", err
		}
		h, err := svc.ProcessEntry(id, item, action, operator, reason, note, follow)
		if err != nil {
			return "", err
		}
		return "已处理\n" + handover.FormatHandover(h), nil

	case "handover-resubmit":
		h, err := svc.ResubmitReturned(id, item, operator, supplement)
		if err != nil {
			return "", err
		}
		return "已补充说明并重新提交\n" + handover.FormatHandover(h), nil

	default:
		return "", fmt.Errorf("未知命令 %q，运行 handover help 查看用法", cmd)
	}
}

func parseTime(name, s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, fmt.Errorf("%s 不能为空，格式为带时区的 RFC3339（如 2026-10-02T08:00:00+08:00）", name)
	}
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return time.Time{}, fmt.Errorf("%s 时间格式无效：%w（应为 RFC3339，如 2026-10-02T08:00:00+08:00）", name, err)
	}
	return t, nil
}

