package handover

import (
	"os"
	"testing"
	"time"
)

func TestProcessEntrySaveFailureReturnsZero(t *testing.T) {
	dir := t.TempDir()
	st, err := Open(dir + "/d.json")
	if err != nil { t.Fatal(err) }
	svc := NewService(st)
	base := time.Date(2026, 10, 2, 8, 0, 0, 0, time.UTC)
	a, _ := svc.CreateShift("岗", "张三", base, base.Add(8*time.Hour), "")
	b, _ := svc.CreateShift("岗", "李四", base.Add(8*time.Hour), base.Add(16*time.Hour), "")
	it, _ := svc.AddItem(a.ID, "事项", SeverityNormal, "", "李四")
	if _, err := svc.CloseShift(a.ID); err != nil { t.Fatal(err) }
	h, _ := svc.CreateHandover(a.ID, b.ID)
	if err := os.Mkdir(st.Path()+".tmp", 0o755); err != nil { t.Fatal(err) }
	got, err := svc.ProcessEntry(h.ID, it.ID, ActionConfirm, "李四", "", "", "")
	if err == nil { t.Fatal("应返回保存错误") }
	if got.ID != "" || got.Position != "" || got.FromShiftID != "" || got.ToShiftID != "" ||
		!got.CreatedAt.IsZero() || got.CompletedAt != nil || len(got.Entries) != 0 {
		t.Fatalf("保存失败应返回零值交接结果：%+v", got)
	}
}
EOF
